use strict;
use warnings;
use bytes;

my $file = shift @ARGV or die "usage: pdf_streams.pl file prefix\n";
my $prefix = shift @ARGV or die "usage: pdf_streams.pl file prefix\n";
open my $fh, '<:raw', $file or die "$file: $!\n";
local $/;
my $pdf = <$fh>;
my $i = 0;
while ($pdf =~ m{/Filter\s+(\[.*?\]|/\w+).*?stream\r?\n}sg) {
    my $filters = $1;
    my $start = $+;
    my $end = index($pdf, "\nendstream", $start);
    next if $end < 0;
    my $data = substr($pdf, $start, $end - $start);
    $data =~ s/\r?\n\z//;
    if ($filters =~ /ASCII85Decode/) {
        $data = ascii85($data);
    }
    my $out = sprintf("%s.%02d.bin", $prefix, $i++);
    open my $of, '>:raw', $out or die "$out: $!\n";
    print {$of} $data;
    close $of;
    print "$out\t$filters\t" . length($data) . "\n";
    pos($pdf) = $end + 10;
}

sub ascii85 {
    my ($in) = @_;
    $in =~ s/\s+//g;
    $in =~ s/~>\z//;
    my $out = '';
    while (length $in) {
        if (substr($in, 0, 1) eq 'z') {
            $out .= "\0\0\0\0";
            substr($in, 0, 1, '');
            next;
        }
        my $n = length($in) >= 5 ? 5 : length($in);
        my $chunk = substr($in, 0, $n, '');
        my $orig = $n;
        $chunk .= 'u' x (5 - $n);
        my $v = 0;
        for my $c (split //, $chunk) {
            my $x = ord($c) - 33;
            die "invalid ASCII85 byte\n" if $x < 0 || $x > 84;
            $v = $v * 85 + $x;
        }
        my $bytes = pack('N', $v);
        $out .= substr($bytes, 0, $orig - 1);
        last if $orig < 5;
    }
    return $out;
}

